    # best[node] = (load, -hops) where load is the bottleneck and -hops breaks ties
    best: Dict[str, Tuple[float, int]] = {src: (float("inf"), 0)}
    parent: Dict[str, Optional[str]] = {src: None}
    visited: Set[str] = set()
    # heap entry: (-load, hops, node) -> min-heap pops highest load, fewest hops first
    heap: List[Tuple[float, int, str]] = [(-float("inf"), 0, src)]

    while heap:
        neg_load, hops, node = heapq.heappop(heap)
        load = -neg_load
        if node in visited:
            continue
        if (load, -hops) < best[node]:
            continue
        visited.add(node)
        if node == dst:
            path: List[str] = []
            cur: Optional[str] = node
            while cur is not None:
                path.append(cur)
                cur = parent[cur]
            path.reverse()
            return (int(best[dst][0]), path)
        for neighbour, w in limits[node].items():
            if neighbour in visited:
                continue
            bottleneck = min(load, w)
            candidate = (bottleneck, -(hops + 1))
            if candidate > best.get(neighbour, (0, 0)):
                best[neighbour] = candidate
                parent[neighbour] = node
                heapq.heappush(heap, (-bottleneck, hops + 1, neighbour))

    return None
